//! Synthetic native semantics. Fresh real-engine/three-backend games remain Root work.
use super::*;
fn catalogue()->Value {serde_json::from_slice(include_bytes!(concat!(env!("OUT_DIR"),"/catalogue.json"))).unwrap()}
fn engine(backend:RulesBackend)->Engine {let mut e=Engine::from_catalogue_value(&catalogue()).unwrap();assert!(e.by_code.contains_key("ASH_219"),"{:?}",e.rejected_cards().unwrap().get("ASH_219"));e.set_rules_backend(backend).unwrap();e}
fn add(e:&Engine,s:&mut State,seat:Seat,code:&str)->CardId {let id=s.next_id;s.next_id+=1;*s.card_mut(id)=Card{present:true,def:*e.by_code.get(code).unwrap_or_else(||panic!("{code}")),owner:seat,..Card::default()};id}
fn unit(e:&Engine,s:&mut State,seat:Seat,code:&str)->CardId {let id=add(e,s,seat,code);e.add_arena(s,id).unwrap();id}
fn board(e:&Engine,seat:Seat)->State {let mut s=State::default();s.active=seat;s.action_player=Some(seat);s.hidden_history_exact=true;s.force_state_exact=true;s.credit_state_exact=true;s.round_limit_wire_present=true;for owner in [seat,seat.other()] {s.player_mut(owner).base=add(e,&mut s,owner,"SOR_023");s.player_mut(owner).leader=add(e,&mut s,owner,"SOR_014");s.player_mut(owner).force_id=add(e,&mut s,owner,"TOKEN_THE_FORCE");for _ in 0..24 {let id=add(e,&mut s,owner,"LOF_254");s.player_mut(owner).resources.push(id).unwrap();}for _ in 0..5 {let id=add(e,&mut s,owner,"LOF_254");s.player_mut(owner).deck.push(id).unwrap();}}s}
fn click(e:&Engine,s:&mut State,label:&str) {let a=e.legal_actions(s).into_iter().find(|a|a.label==label).unwrap_or_else(||panic!("missing {label}: {:?}",e.legal_actions(s)));*s=e.apply(s,&a).unwrap();}
fn start(e:&Engine,s:&mut State,source:CardId) {s.source=source;s.active=s.card(source).owner;let p=e.card_programs(s,source)[0];e.begin_program(s,p,ProgramContinuation::Finish).unwrap();}
#[test]fn arena_payment_whole_source_scalar_guards_and_capacity(){
 let original=crate::arena_payment_exhaust_contract::profile();assert_eq!(crate::arena_payment_exhaust_contract::prepare(&original),Ok(true));
 let mut alias=original.clone();alias["setCode"]=json!("SYNTH_JOD_ALIAS");assert!(crate::arena_payment_exhaust_contract::prepare(&alias).is_err());
 for (path,value) in [("/card/keywords",json!([])),("/keywordValues/sentinel",json!(2)),("/card/cost",json!(4)),("/card/unique",json!(false)),("/sourceHash",json!("foreign")),("/baseClass",json!("EventCard")),("/abilities/card/0/optional",json!(false)),("/abilities/card/0/effect/amount/value",json!(0)),("/abilities/card/0/effect/target",json!("enemyPlayer")),("/abilities/card/0/effect/canCancelDuringPayment",json!(true)),("/abilities/card/0/ifYouDo/targetResolver/choices/entries/0/effect/target/receiver/path",json!(["player"])),("/abilities/card/0/ifYouDo/targetResolver/choices/entries/0/labelParts/0/value",json!("Ground"))] {let mut bad=original.clone();*bad.pointer_mut(path).unwrap()=value;assert!(crate::arena_payment_exhaust_contract::prepare(&bad).is_err(),"{path}");let mut v=catalogue();let at=v["cards"].as_array().unwrap().iter().position(|e|e["setCode"]=="ASH_219").unwrap();v["cards"][at]=bad;let e=Engine::from_catalogue_value(&v).unwrap();assert!(!e.by_code.contains_key("ASH_219"),"constructor {path}");}
 for scope in ["", "/abilities/card/0", "/abilities/card/0/effect", "/abilities/card/0/ifYouDo", "/abilities/card/0/ifYouDo/targetResolver"] {let mut bad=original.clone();bad.pointer_mut(scope).unwrap().as_object_mut().unwrap().insert("unknown".into(),json!(true));assert!(crate::arena_payment_exhaust_contract::prepare(&bad).is_err());}
 let mut bad=original.clone();bad["abilities"]["card"].as_array_mut().unwrap().push(json!({"trigger":"whenPlayed","effect":{"kind":"noAction"}}));assert!(crate::arena_payment_exhaust_contract::prepare(&bad).is_err());
 let a=serde_json::from_value::<crate::ability_ir::Ability>(original["abilities"]["card"][0].clone());assert!(a.is_err(),"standalone nested choice must not gain partial scalar admission");

}
#[test]fn arena_payment_normal_play_decline_both_arenas_and_native_backends(){
 for backend in [RulesBackend::Auto,RulesBackend::Interpreter] {let e=engine(backend);for seat in [Seat::P1,Seat::P2] {for label in ["Space","Ground"] {let mut s=board(&e,seat);let own=unit(&e,&mut s,seat,"LOF_254");let enemy=unit(&e,&mut s,seat.other(),"HMW_135");let space=unit(&e,&mut s,seat.other(),"SOR_178");let old=unit(&e,&mut s,seat,"SOR_178");s.card_mut(old).exhausted=true;s.card_mut(enemy).damage=1;
 let source=add(&e,&mut s,seat,"ASH_219");s.player_mut(seat).hand.push(source).unwrap();let action=e.card_action(&s,source);assert!(e.legal_actions(&s).contains(&action));let ready=e.ready_resources(&s,seat);s=e.apply(&s,&action).unwrap();assert!(e.in_arena(&s,source));assert!(s.card(source).exhausted);assert_eq!(ready-e.ready_resources(&s,seat),5);assert_eq!(s.decision,Decision::AbilityOptional);
 let mut decline=s;click(&e,&mut decline,"Pass");assert_eq!(e.ready_resources(&decline,seat),ready-5);assert!(!decline.card(own).exhausted);assert!(!decline.card(space).exhausted);
 click(&e,&mut s,"Trigger");assert_eq!(e.ready_resources(&s,seat),ready-9);assert_eq!(e.legal_actions(&s).iter().map(|a|a.label.as_str()).collect::<Vec<_>>(),vec!["Space","Ground"]);click(&e,&mut s,label);assert_eq!(s.card(own).exhausted,label=="Ground");assert_eq!(s.card(enemy).exhausted,label=="Ground");assert_eq!(s.card(space).exhausted,label=="Space");assert!(s.card(old).exhausted);assert_eq!(s.card(enemy).damage,1);assert_eq!(s.decision,Decision::Window);assert_eq!(e.keyword_amount(&s,source,"sentinel"),1);
 }}}
}
#[test]fn arena_payment_credits_forced_skip_all_credit_zero_remainder_and_no_cancel(){
 for seat in [Seat::P1,Seat::P2] {for mode in ["all","skip","forced"] {let e=engine(RulesBackend::Auto);let mut s=board(&e,seat);let source=unit(&e,&mut s,seat,"ASH_219");let target=unit(&e,&mut s,seat.other(),"SOR_178");let credits=if mode=="forced"{1}else{4};e.create_credit_tokens(&mut s,seat,credits).unwrap();if mode=="forced" {for (i,id) in s.player(seat).resources.as_slice().to_vec().into_iter().enumerate(){s.card_mut(id).exhausted=i>=3;}}
 let before=e.ready_resources(&s,seat);start(&e,&mut s,source);assert_eq!(s.decision,Decision::AbilityOptional);click(&e,&mut s,"Trigger");assert!(matches!(s.decision,Decision::CreditMenu|Decision::CreditAmount));assert_eq!(s.resource_payment.purpose,crate::resource_payment::PaymentPurpose::Effect);assert!(!s.resource_payment.can_cancel);assert!(!e.legal_actions(&s).iter().any(|a|a.arg.as_ref().and_then(Value::as_str)==Some("cancel")));let pending=e.snapshot(&s);assert!(pending.get("directUnitPlayCreditState").is_none());assert!(e.load_state(&pending).is_err(),"effect payment must not bypass direct unit pending importer");let copy=s;assert_eq!(copy.zobrist(),s.zobrist());
 if mode=="skip" {click(&e,&mut s,"Pay costs without Credit tokens");assert_eq!(e.ready_resources(&s,seat),before-4);}else if mode=="forced"{click(&e,&mut s,"Use 1 Credit");assert_eq!(e.ready_resources(&s,seat),0);}else{click(&e,&mut s,"Select amount");click(&e,&mut s,"#4");assert_eq!(e.ready_resources(&s,seat),before);}
 assert!(s.ability_succeeded);assert_eq!(e.legal_actions(&s).iter().map(|a|a.label.as_str()).collect::<Vec<_>>(),vec!["Space","Ground"]);click(&e,&mut s,"Space");assert!(s.card(target).exhausted);assert_eq!(e.available_credit_count(&s,seat),if mode=="skip"{4}else{0});
 }}
}
#[test]fn arena_payment_empty_arena_all_exhausted_source_gone_and_large_batch(){
 let e=engine(RulesBackend::Auto);for seat in [Seat::P1,Seat::P2] {let mut s=board(&e,seat);let source=unit(&e,&mut s,seat,"ASH_219");s.card_mut(source).exhausted=true;let target=unit(&e,&mut s,seat.other(),"LOF_254");s.card_mut(target).exhausted=true;start(&e,&mut s,source);click(&e,&mut s,"Trigger");assert_eq!(s.decision,Decision::Window,"empty space auto-ground, even all exhausted");assert_eq!(s.ability_result,0);assert_eq!(e.ready_resources(&s,seat),20);
 let mut s=board(&e,seat);let old=unit(&e,&mut s,seat,"ASH_219");let incoming=add(&e,&mut s,seat,"ASH_219");s.player_mut(seat).hand.push(incoming).unwrap();e.play_unit_with_payment(&mut s,incoming,false).unwrap();assert_eq!(s.decision,Decision::Unique);e.settle_enter_triggers(&mut s,Some(incoming)).unwrap();assert!(!e.in_arena(&s,incoming));assert!(e.in_arena(&s,old));assert_eq!(s.decision,Decision::AbilityOptional);click(&e,&mut s,"Trigger");assert!(s.card(old).exhausted);assert_eq!(e.ready_resources(&s,seat),15);
 let mut s=board(&e,seat);let source=unit(&e,&mut s,seat,"ASH_219");let mut targets=vec![];for i in 0..128 {targets.push(unit(&e,&mut s,if i%2==0{seat}else{seat.other()},"SOR_178"));}start(&e,&mut s,source);click(&e,&mut s,"Trigger");click(&e,&mut s,"Space");assert!(targets.iter().all(|id|s.card(*id).exhausted));assert!(!s.card(source).exhausted);
 }
 assert_eq!(std::mem::size_of::<State>(),38312);
}
#[test]fn arena_payment_intrinsic_sentinel_and_phase_effect_payment_does_not_consume_mouse(){
 let e=engine(RulesBackend::Auto);let mut s=board(&e,Seat::P1);let jod=unit(&e,&mut s,Seat::P1,"ASH_219");s.card_mut(jod).exhausted=true;let attacker=unit(&e,&mut s,Seat::P2,"LOF_254");let other=unit(&e,&mut s,Seat::P1,"LOF_254");assert_eq!(e.attack_targets(&s,attacker,false),vec![jod]);assert!(!e.attack_targets(&s,attacker,false).contains(&other));
 let mouse=add(&e,&mut s,Seat::P1,"ASH_237");s.player_mut(Seat::P1).discard.push(mouse).unwrap();s.source=mouse;let p=e.card_programs(&s,mouse)[0];e.begin_program(&mut s,p,ProgramContinuation::Finish).unwrap();assert_eq!(s.player_phase.len,1);let before=s.player_phase;start(&e,&mut s,jod);click(&e,&mut s,"Trigger");assert_eq!(s.player_phase,before,"matchCardEffectResourcePayments=false");assert!(s.card(jod).exhausted);assert!(s.card(other).exhausted);
}
#[test]fn arena_payment_actual_constructor_complete_set_delta(){
 let Ok(path)=std::env::var("SWU_JOD_BASELINE_POOL") else {return;};let old:Value=serde_json::from_slice(&std::fs::read(path).unwrap()).unwrap();let e=engine(RulesBackend::Auto);let new=e.compiled_pool().unwrap();let codes=|p:&Value|p["cards"].as_array().unwrap().iter().map(|c|c["setCode"].as_str().unwrap().to_owned()).collect::<std::collections::BTreeSet<_>>();let(a,b)=(codes(&old),codes(&new));assert!(a.is_subset(&b));assert_eq!(b.difference(&a).map(String::as_str).collect::<Vec<_>>(),vec!["ASH_219"]);eprintln!("JOD_CONSTRUCTOR old={} new={} gained={:?}",a.len(),b.len(),b.difference(&a).collect::<Vec<_>>());if let Ok(out)=std::env::var("SWU_JOD_REPORT_DIR"){std::fs::create_dir_all(&out).unwrap();std::fs::write(std::path::Path::new(&out).join("pool.json"),serde_json::to_vec_pretty(&new).unwrap()).unwrap();std::fs::write(std::path::Path::new(&out).join("rules.json"),serde_json::to_vec_pretty(&e.rules_backend_report()).unwrap()).unwrap();}
}

#[test]fn arena_payment_unaffordable_optional_payment_is_absent_after_normal_play(){
 let e=engine(RulesBackend::Auto);for remaining in [0usize,3] {let mut s=board(&e,Seat::P1);for (i,id) in s.player(Seat::P1).resources.as_slice().to_vec().into_iter().enumerate(){s.card_mut(id).exhausted=i>=remaining+5;}let target=unit(&e,&mut s,Seat::P2,"SOR_178");let source=add(&e,&mut s,Seat::P1,"ASH_219");s.player_mut(Seat::P1).hand.push(source).unwrap();let a=e.card_action(&s,source);s=e.apply(&s,&a).unwrap();assert_eq!(e.ready_resources(&s,Seat::P1),remaining);assert_eq!(s.decision,Decision::Window);assert!(!s.card(target).exhausted);assert!(e.in_arena(&s,source));}
}

#[test]fn arena_payment_manual_zero_change_token_leader_and_saboteur_domains(){
 let e=engine(RulesBackend::Auto);for seat in [Seat::P1,Seat::P2] {for label in ["Space","Ground"] {let mut s=board(&e,seat);let source=unit(&e,&mut s,seat,"ASH_219");let space=unit(&e,&mut s,seat.other(),"SOR_178");let token=unit(&e,&mut s,seat.other(),"TOKEN_BATTLE_DROID");let leader=s.player(seat.other()).leader;s.card_mut(leader).deployed=true;e.add_arena(&mut s,leader).unwrap();for id in [source,space,token,leader]{s.card_mut(id).exhausted=true;}start(&e,&mut s,source);click(&e,&mut s,"Trigger");assert_eq!(e.legal_actions(&s).iter().map(|a|a.label.as_str()).collect::<Vec<_>>(),vec!["Space","Ground"]);click(&e,&mut s,label);assert_eq!(s.ability_result,0);assert_eq!(e.ready_resources(&s,seat),20);assert_eq!(s.decision,Decision::Window);
 let mut s=board(&e,seat);let source=unit(&e,&mut s,seat,"ASH_219");let token=unit(&e,&mut s,seat.other(),"TOKEN_BATTLE_DROID");let leader=s.player(seat.other()).leader;s.card_mut(leader).deployed=true;e.add_arena(&mut s,leader).unwrap();start(&e,&mut s,source);click(&e,&mut s,"Trigger");assert!(s.card(token).exhausted&&s.card(leader).exhausted);
 }}let mut s=board(&e,Seat::P1);let source=unit(&e,&mut s,Seat::P1,"ASH_219");s.card_mut(source).exhausted=true;let sab=unit(&e,&mut s,Seat::P2,"SEC_160");assert_eq!(e.keyword_amount(&s,sab,"saboteur"),1);assert!(e.attack_targets(&s,sab,false).contains(&s.player(Seat::P1).base));let space=unit(&e,&mut s,Seat::P2,"SOR_178");assert!(e.attack_targets(&s,space,false).contains(&s.player(Seat::P1).base));
}

#[test]fn arena_payment_requires_recorded_global_order_and_exact_runtime_program(){
 let mut c=catalogue();c["cards"].as_array_mut().unwrap().retain(|v|v["setCode"].as_str().is_some_and(|code|code.starts_with("TOKEN_")||["ASH_219","SOR_023","SOR_014","LOF_254"].contains(&code)));let e=Engine::from_catalogue_value(&c).unwrap();assert!(e.needs_modal_arena_order());let mut s=board(&e,Seat::P1);for seat in [Seat::P1,Seat::P2]{s.player_mut(seat).force_held=true;}let source=unit(&e,&mut s,Seat::P1,"ASH_219");let p=e.card_programs(&s,source)[0];assert!(crate::arena_payment_exhaust_contract::program(e.program(p)));let wire=e.snapshot(&s);e.load_state(&wire).unwrap();let mut missing=wire.clone();missing.as_object_mut().unwrap().remove("arenaUnitOrder");assert!(e.load_state(&missing).unwrap_err().contains("arenaUnitOrder"));s.source=source;s.arena_order_exact=false;let before=s;assert!(e.begin_program(&mut s,p,ProgramContinuation::Finish).unwrap_err().contains("arena order"));assert_eq!(s,before);
 for mutation in 0..3 {let mut broken=e.program(p).clone();match mutation {0=>broken.optional=false,1=>if let Instruction::IfResult{skip}=&mut broken.instructions[1]{*skip=3},_=>{broken.instructions.remove(0);}};assert!(!crate::arena_payment_exhaust_contract::program(&broken));}
 let mut e=e;let program=e.catalogue.as_mut().unwrap().programs.get_mut(p as usize).unwrap();program.optional=false;s.arena_order_exact=true;let before=s;assert!(e.begin_program(&mut s,p,ProgramContinuation::Finish).is_err());assert_eq!(s,before);
}

#[test]fn arena_payment_typed_marker_excludes_existing_unpaid_modal_arena_families(){
 let e=engine(RulesBackend::Auto);let mut unpaid=0;let mut paid=0;for p in &e.catalogue.as_ref().unwrap().programs {let menu=p.instructions.iter().any(|i|matches!(i,Instruction::ModalChoice(_)));let exhaust=p.instructions.iter().any(|i|matches!(i,Instruction::Apply(Effect::Exhaust{target:Target::ArenaList(_)})));let payment=p.instructions.iter().any(|i|matches!(i,Instruction::Apply(Effect::PayAdjustedResources{..})));if menu&&exhaust&&!payment {unpaid+=1;assert!(!crate::arena_payment_exhaust_contract::requires(p));}if crate::arena_payment_exhaust_contract::requires(p){paid+=1;assert!(crate::arena_payment_exhaust_contract::program(p));}}
 assert!(unpaid>0,"actual admitted Lightmaker/modal exhaust controls must be exercised");assert!(paid>0,"new paid source must be exercised");
}

#[test]fn arena_payment_unreviewed_alias_rejected_on_public_and_copy_origin_routes(){
 let mut c=catalogue();let mut alias=crate::arena_payment_exhaust_contract::profile();alias["setCode"]=json!("SYNTH_JOD_ALIAS");c["cards"].as_array_mut().unwrap().push(alias);
 let e=Engine::from_catalogue_value(&c).unwrap();assert!(e.by_code.contains_key("ASH_219"));assert!(!e.by_code.contains_key("SYNTH_JOD_ALIAS"));assert!(e.rejected_cards().unwrap().contains_key("SYNTH_JOD_ALIAS"));
 let mut pool=e.compiled_pool().unwrap();let mut alias=pool["cards"].as_array().unwrap().iter().find(|v|v["setCode"]=="ASH_219").unwrap().clone();alias["setCode"]=json!("SYNTH_JOD_ALIAS");pool["cards"].as_array_mut().unwrap().push(alias);assert!(Engine::from_compiled_pool_bytes(&serde_json::to_vec(&pool).unwrap(),&serde_json::to_vec(&c).unwrap()).is_err());
 for backend in [RulesBackend::Auto,RulesBackend::Interpreter] {let mut e=Engine::from_catalogue_value(&c).unwrap();e.set_rules_backend(backend).unwrap();for seat in [Seat::P1,Seat::P2]{let mut s=board(&e,seat);let old=unit(&e,&mut s,seat,"ASH_219");let incoming=add(&e,&mut s,seat,"ASH_219");s.player_mut(seat).hand.push(incoming).unwrap();e.play_unit_with_payment(&mut s,incoming,false).unwrap();assert_eq!(s.decision,Decision::Unique);assert!(e.in_arena(&s,old)&&e.in_arena(&s,incoming));}}
 let mut s=board(&e,Seat::P1);let d=unit(&e,&mut s,Seat::P1,"ASH_037");let a=unit(&e,&mut s,Seat::P1,"HMW_135");s.source=d;e.begin_support_attack(&mut s,a).unwrap();click(&e,&mut s,"Pass attack");let mut wire=e.snapshot(&s);assert_eq!(wire["supportGrants"].as_array().unwrap().len(),1);wire["supportGrants"][0]["sourcePrograms"]["setCode"]=json!("SYNTH_JOD_ALIAS");assert!(e.load_state(&wire).is_err());
 let base:Value=serde_json::from_slice(include_bytes!(concat!(env!("OUT_DIR"),"/catalogue.json"))).unwrap();let old=Engine::from_catalogue_value(&base).unwrap().compiled_pool().unwrap();let codes=|v:&Value|v["cards"].as_array().unwrap().iter().map(|r|r["setCode"].as_str().unwrap().to_owned()).collect::<std::collections::BTreeSet<_>>();assert_eq!(codes(&old),codes(&e.compiled_pool().unwrap()));
}
